/**
 * Shallow parsers for the Android native project.
 *
 * DELIBERATELY SHALLOW. ExpoPulse has no XML parser dependency and will not add
 * one: these files are, in the overwhelming majority of cases, generated by
 * `expo prebuild` from a template, so their shape is known and stable. Regex
 * extraction over a known template is a good trade for a zero-dependency
 * analyzer; it is a bad trade for arbitrary XML, and we do not pretend
 * otherwise.
 *
 * Consequences we accept, so that callers can reason about confidence:
 *   - Attribute order and whitespace are tolerated, but namespace prefixes
 *     other than `android:` are not recognised.
 *   - Gradle is read as text, so a value computed at configuration time
 *     (`targetSdkVersion someFunction()`) reads as absent, not as wrong.
 *   - Anything unrecognised degrades to empty/null. These functions never
 *     throw, and a malformed native file must never fail an analysis run.
 */

import fs from 'node:fs/promises'
import path from 'node:path'

/** One `<uses-permission>` declaration, with the line it was declared on. */
export interface PermissionDecl {
  /** Bare permission name with the `android.permission.` prefix stripped. */
  name: string
  /** Fully qualified value exactly as written in the manifest. */
  raw: string
  /** 1-based line within AndroidManifest.xml. */
  line: number
}

/** Facts extracted from AndroidManifest.xml. */
export interface ManifestFacts {
  /** Project-relative path the facts came from. */
  file: string
  permissions: PermissionDecl[]
  /**
   * Value of `android:usesCleartextTraffic` on `<application>`, or null when the
   * attribute is absent (the platform default, which varies by targetSdk).
   */
  usesCleartextTraffic: boolean | null
  /** Value of `android:allowBackup`, or null when not declared. */
  allowBackup: boolean | null
  /** Line of the `<application>` open tag, for findings about its attributes. */
  applicationLine: number | null
}

/** Facts extracted from the app and root `build.gradle` files. */
export interface GradleFacts {
  /** Project-relative path of app/build.gradle, when it was readable. */
  appFile: string | null
  /** Project-relative path of the root build.gradle, when it was readable. */
  rootFile: string | null
  compileSdk: SdkValue | null
  targetSdk: SdkValue | null
  minSdk: SdkValue | null
  /** `minifyEnabled` in the release buildType. */
  minifyEnabled: boolean | null
  shrinkResources: boolean | null
  /** True when per-ABI splits or the separate-CPU-build flag are switched on. */
  abiSplitsEnabled: boolean
  /** Value of the `enableProguardInReleaseBuilds` gradle property, if present. */
  proguardInRelease: boolean | null
  /** Line of `enableSeparateBuildPerCPUArchitecture`, when it was found. */
  abiFlagLocation: SourceRef | null
}

/** A resolved SDK level plus where it was found, since it may be in either file. */
export interface SdkValue {
  value: number
  /** Project-relative path of the file the value was read from. */
  file: string
  line: number
}

/** A file/line pair for attaching a finding to a real location. */
export interface SourceRef {
  file: string
  line: number
}

/** Relative path of the manifest in a standard Expo/RN Android project. */
export const MANIFEST_RELATIVE = 'android/app/src/main/AndroidManifest.xml'
export const APP_GRADLE_RELATIVE = 'android/app/build.gradle'
export const ROOT_GRADLE_RELATIVE = 'android/build.gradle'
export const GRADLE_PROPERTIES_RELATIVE = 'android/gradle.properties'

/** Read a text file, or null when it is missing or unreadable. */
async function readTextOrNull(absolutePath: string): Promise<string | null> {
  try {
    return await fs.readFile(absolutePath, 'utf8')
  } catch {
    // Missing file, permission error, or a directory where a file was expected.
    // All three mean "nothing to analyse here", never "abort the run".
    return null
  }
}

/**
 * Blank out XML comments while preserving byte offsets and newlines.
 *
 * Commented-out permissions are extremely common in generated manifests (Expo
 * emits some as examples, and developers comment things out while debugging).
 * Reporting them would be a false positive. Replacing the comment body with
 * spaces rather than deleting it keeps every later line number correct, which
 * matters because findings point at real lines.
 */
function blankXmlComments(xml: string): string {
  return xml.replace(/<!--[\s\S]*?-->/g, (match) => match.replace(/[^\n]/g, ' '))
}

/** Same idea for Gradle: neutralise `//` and block comments, keep line count. */
function blankGradleComments(source: string): string {
  return source
    .replace(/\/\*[\s\S]*?\*\//g, (m) => m.replace(/[^\n]/g, ' '))
    .replace(/\/\/[^\n]*/g, (m) => ' '.repeat(m.length))
}

/** 1-based line number of a character offset. */
function lineAt(source: string, index: number): number {
  let line = 1
  for (let i = 0; i < index && i < source.length; i++) {
    if (source[i] === '\n') line++
  }
  return line
}

/**
 * Interpret a Gradle/XML boolean literal.
 *
 * Returns null for anything that is not a plain `true`/`false`, e.g. a
 * reference to a project property. "Unknown" is the honest answer there, and it
 * keeps rules from asserting something they cannot see.
 */
function parseBool(token: string | undefined): boolean | null {
  if (token === undefined) return null
  const value = token.trim().toLowerCase()
  if (value === 'true') return true
  if (value === 'false') return false
  return null
}

/**
 * Parse AndroidManifest.xml.
 *
 * Returns null when the manifest is absent — a prebuilt project without one is
 * unusual enough that having no opinion beats guessing.
 */
export async function parseManifest(root: string): Promise<ManifestFacts | null> {
  const absolute = path.join(root, MANIFEST_RELATIVE)
  const raw = await readTextOrNull(absolute)
  if (raw === null) return null

  const xml = blankXmlComments(raw)

  const permissions: PermissionDecl[] = []
  // Match the tag first, then the attribute, so attribute order and any extra
  // attributes (`tools:node`, `android:maxSdkVersion`) do not break the match.
  const tagPattern = /<uses-permission\b[^>]*?\/?>/g
  for (let m = tagPattern.exec(xml); m !== null; m = tagPattern.exec(xml)) {
    const tag = m[0]
    const nameMatch = /android:name\s*=\s*"([^"]*)"/.exec(tag)
    const value = nameMatch?.[1]?.trim()
    if (!value) continue
    permissions.push({
      // Rules read the short form; `raw` keeps the original for excerpts.
      name: value.replace(/^android\.permission\./, ''),
      raw: value,
      line: lineAt(xml, m.index),
    })
  }

  const appMatch = /<application\b[^>]*>/.exec(xml)
  const appTag = appMatch?.[0] ?? ''

  return {
    file: MANIFEST_RELATIVE,
    permissions,
    usesCleartextTraffic: parseBool(
      /android:usesCleartextTraffic\s*=\s*"([^"]*)"/.exec(appTag)?.[1],
    ),
    allowBackup: parseBool(/android:allowBackup\s*=\s*"([^"]*)"/.exec(appTag)?.[1]),
    applicationLine: appMatch ? lineAt(xml, appMatch.index) : null,
  }
}

/**
 * Find an SDK level in one gradle file.
 *
 * Handles the three spellings that coexist in the RN/Expo ecosystem:
 *   compileSdkVersion 35          (legacy DSL)
 *   compileSdk = 35               (AGP 7+ property)
 *   compileSdkVersion = 35        (root `ext {}` block)
 *
 * Expo's template puts the real numbers in the ROOT build.gradle `ext` block and
 * has app/build.gradle reference them via `rootProject.ext.compileSdkVersion`,
 * so a literal is frequently only present in one of the two files. The
 * reference form intentionally does not match — it carries no number.
 */
type SdkKind = 'compile' | 'target' | 'min'

function findSdk(source: string, file: string, kind: SdkKind): SdkValue | null {
  const name = `${kind}Sdk`
  // `(?:Version)?` covers both DSL spellings; `=` is optional for the same reason.
  const pattern = new RegExp(`\\b${name}(?:Version)?\\s*=?\\s*(\\d{1,2})\\b`)
  const match = pattern.exec(source)
  const digits = match?.[1]
  if (!match || digits === undefined) return null
  const value = Number.parseInt(digits, 10)
  if (!Number.isFinite(value)) return null
  return { value, file, line: lineAt(source, match.index) }
}

/**
 * Parse app/build.gradle and the root build.gradle together.
 *
 * They are handled as a pair because SDK levels are split across them in the
 * standard Expo template (see `findSdk`). The app file wins when both define a
 * value, matching Gradle's own precedence for a locally assigned property.
 *
 * `gradle.properties` is read too, because that is where Expo's template
 * actually defines the flags that app/build.gradle references by name — without
 * it, `minifyEnabled enableProguardInReleaseBuilds` resolves to "unknown" on
 * every real Expo project and the shrinking rules never fire.
 *
 * Returns null only when NEITHER build.gradle is readable.
 */
export async function parseGradle(root: string): Promise<GradleFacts | null> {
  const [appRaw, rootRaw, propsRaw] = await Promise.all([
    readTextOrNull(path.join(root, APP_GRADLE_RELATIVE)),
    readTextOrNull(path.join(root, ROOT_GRADLE_RELATIVE)),
    readTextOrNull(path.join(root, GRADLE_PROPERTIES_RELATIVE)),
  ])
  if (appRaw === null && rootRaw === null) return null

  const app = appRaw === null ? null : blankGradleComments(appRaw)
  const rootGradle = rootRaw === null ? null : blankGradleComments(rootRaw)
  // `#` is the comment character in a properties file, not `//`.
  const props = propsRaw === null ? null : propsRaw.replace(/#[^\n]*/g, (m) => ' '.repeat(m.length))

  /** Prefer the app module's own literal, then fall back to the root ext block. */
  const pickSdk = (kind: SdkKind): SdkValue | null => {
    const fromApp = app === null ? null : findSdk(app, APP_GRADLE_RELATIVE, kind)
    if (fromApp) return fromApp
    return rootGradle === null ? null : findSdk(rootGradle, ROOT_GRADLE_RELATIVE, kind)
  }

  // Shrinking flags are declared in the app module but may be defined elsewhere,
  // so variable resolution searches the properties file and root script too.
  const scopes = [app, props, rootGradle]
  const minifyEnabled = app === null ? null : findReleaseFlag(app, 'minifyEnabled', scopes)
  const shrinkResources = app === null ? null : findReleaseFlag(app, 'shrinkResources', scopes)

  const abiFlag = findAbiSplitFlag(app, rootGradle, props)

  return {
    appFile: appRaw === null ? null : APP_GRADLE_RELATIVE,
    rootFile: rootRaw === null ? null : ROOT_GRADLE_RELATIVE,
    compileSdk: pickSdk('compile'),
    targetSdk: pickSdk('target'),
    minSdk: pickSdk('min'),
    minifyEnabled: minifyEnabled?.value ?? null,
    shrinkResources: shrinkResources?.value ?? null,
    abiSplitsEnabled: abiFlag?.enabled ?? false,
    proguardInRelease: findProguardFlag(app, rootGradle, props),
    abiFlagLocation: abiFlag?.location ?? null,
  }
}

/**
 * Read a shrinking flag such as `minifyEnabled`.
 *
 * Expo's template writes `minifyEnabled enableProguardInReleaseBuilds` — a
 * variable, not a literal — so a bare name is resolved one hop through its
 * `def`/`ext` assignment. Without that hop every Expo project would read as
 * "unknown" and the minify rule would never fire.
 *
 * Debug buildTypes are not excluded structurally (that needs brace matching);
 * instead we take the LAST occurrence, because in the generated template the
 * release block follows debug. This is a heuristic and is noted on the rule.
 */
function findReleaseFlag(
  source: string,
  flag: string,
  scopes: (string | null)[],
): { value: boolean | null } | null {
  // `minifyEnabled true` and `minifyEnabled = true` both occur in the wild.
  const pattern = new RegExp(`\\b${flag}\\s*=?\\s+([A-Za-z_][\\w.]*|true|false)`, 'g')
  let last: string | undefined
  for (let m = pattern.exec(source); m !== null; m = pattern.exec(source)) {
    if (m[1] !== undefined) last = m[1]
  }
  if (last === undefined) return null

  const direct = parseBool(last)
  if (direct !== null) return { value: direct }

  // Resolve one level of indirection: `def enableProguardInReleaseBuilds = true`,
  // an `ext` assignment, or — the Expo template's actual location — a
  // gradle.properties entry.
  return { value: resolveBooleanVariable(last, scopes) }
}

/**
 * Resolve `name = true|false` across the supplied files. One hop only, by design:
 * chasing arbitrary Gradle expressions is what a real Gradle run is for.
 */
function resolveBooleanVariable(name: string, scopes: (string | null)[]): boolean | null {
  // Strip any `rootProject.ext.` / `project.` qualifier to get the bare name.
  const bare = name.split('.').pop() ?? name
  const escaped = bare.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
  const pattern = new RegExp(`\\b${escaped}\\s*=\\s*(true|false)\\b`)
  for (const source of scopes) {
    if (source === null) continue
    const parsed = parseBool(pattern.exec(source)?.[1])
    if (parsed !== null) return parsed
  }
  return null
}

/**
 * Detect per-ABI output configuration.
 *
 * Two forms matter: the RN template's `enableSeparateBuildPerCPUArchitecture`
 * property, and an explicit `splits { abi { enable true } }` block. Either one
 * means users are not downloading every architecture.
 *
 * NOTE: this says nothing about Android App Bundles. AAB delivery solves the
 * same problem at the store layer and is the Expo/EAS default, which is why the
 * rule built on this is `info` and hedged rather than a warning.
 */
function findAbiSplitFlag(
  app: string | null,
  rootGradle: string | null,
  props: string | null,
): { enabled: boolean; location: SourceRef | null } | null {
  const candidates: { source: string; file: string }[] = []
  if (app !== null) candidates.push({ source: app, file: APP_GRADLE_RELATIVE })
  // The RN/Expo template sets this in gradle.properties, so check it first for
  // the authoritative value.
  if (props !== null) candidates.push({ source: props, file: GRADLE_PROPERTIES_RELATIVE })
  if (rootGradle !== null) candidates.push({ source: rootGradle, file: ROOT_GRADLE_RELATIVE })
  if (candidates.length === 0) return null

  for (const { source, file } of candidates) {
    const flag = /\benableSeparateBuildPerCPUArchitecture\s*=?\s*(true|false)\b/.exec(source)
    if (flag) {
      const enabled = parseBool(flag[1]) ?? false
      if (enabled) return { enabled: true, location: { file, line: lineAt(source, flag.index) } }
    }

    // `splits { abi { enable true ... } }` — match the abi block then its flag.
    const abiBlock = /\babi\s*\{[\s\S]{0,400}?\benable\s+(true|false)\b/.exec(source)
    if (abiBlock && parseBool(abiBlock[1]) === true) {
      return { enabled: true, location: { file, line: lineAt(source, abiBlock.index) } }
    }
  }

  // Report the location of the (disabled) flag when we have one, so a finding
  // can point at the line the developer needs to change.
  for (const { source, file } of candidates) {
    const flag = /\benableSeparateBuildPerCPUArchitecture\b/.exec(source)
    if (flag) return { enabled: false, location: { file, line: lineAt(source, flag.index) } }
  }
  return { enabled: false, location: null }
}

/**
 * Value of `enableProguardInReleaseBuilds`. Checked in gradle.properties first,
 * since that is where the Expo/RN template declares it.
 */
function findProguardFlag(
  app: string | null,
  rootGradle: string | null,
  props: string | null,
): boolean | null {
  for (const source of [props, app, rootGradle]) {
    if (source === null) continue
    const match = /\benableProguardInReleaseBuilds\s*=\s*(true|false)\b/.exec(source)
    const parsed = parseBool(match?.[1])
    if (parsed !== null) return parsed
  }
  return null
}
